 static double[] HubNumbers(object value){return ((object[])value).Select(Convert.ToDouble).ToArray();}
 static void HubSeatCheck(Body2 hub){
  var faces=((object[])hub.GetFaces()).Cast<Face2>().ToArray();var holes=faces.Select(f=>(Surface)f.GetSurface()).Where(s=>s.IsCylinder()).Select(s=>(double[])s.CylinderParams).Where(c=>Math.Abs(c[6]-.00512)<1e-8).ToArray();if(holes.Length!=4)throw new Exception("Restored hub does not have four mounting holes");
  foreach(var h in holes){var error=new[]{new[]{.078,0d},new[]{-.078,0d},new[]{0d,.078},new[]{0d,-.078}}.Min(p=>Math.Sqrt(Math.Pow(h[0]-p[0],2)+Math.Pow(h[1]-p[1],2)));if(error>1e-7||Math.Abs(h[5])<.999999)throw new Exception("Restored hub mounting pattern is not coaxial with the rim");}
  var seat=faces.Where(f=>((Surface)f.GetSurface()).IsPlane()).OrderByDescending(f=>f.GetArea()).First();var box=(double[])seat.GetBox();if(Math.Abs(box[2]+.0254)>1e-8||Math.Abs(box[5]+.0254)>1e-8)throw new Exception("Hub mounting face is not seated against rim");
 }
 static void HubBind(Dictionary<string,object> d,Component2 instance){object info;var refs=((object[])instance.GetBodies3(-1,out info)).Cast<Body2>().Select(b=>(object)new Dictionary<string,object>{{"Kind","body"},{"Name",instance.Name2+" / "+b.Name},{"ComponentReference",Ref(model,instance)},{"Reference",Ref(model,b)}}).ToArray();d["Selections"]=refs;d["BodyIds"]=refs.Cast<Dictionary<string,object>>().Select(s=>BodyIdentity((string)s["ComponentReference"],(string)s["Reference"])).ToArray();d["AppearanceSelections"]=refs;d["GeometryDirectory"]=null;d["AppearanceDirectory"]=null;d["AppearancePackageState"]="pending";}
 static void HubRecoverCopyBindings(){
  if(record.Instances.Count>0)return;CheckOriginals();
  var receipt=(Dictionary<string,object>)json.DeserializeObject(File.ReadAllText(Path.Combine(Path.GetDirectoryName(record.Source),"working-assembly.json")));var recovered=new Dictionary<string,InstanceRecord>();
  Action<Dictionary<string,object>> visit=null;visit=g=>{var part=(string)g["Part"];var reference=(string)g["ComponentReference"];if(!string.IsNullOrEmpty(part)&&!string.IsNullOrEmpty(reference)){var target=record.Files[part];var c=instances.Values.Single(i=>string.Equals(i.GetPathName(),target,StringComparison.OrdinalIgnoreCase));recovered[reference]=new InstanceRecord{Id=c.GetID(),Name=c.Name2,Path=part,Reference=reference,Transform=(double[])c.Transform2.ArrayData};}object members;if(g.TryGetValue("Members",out members)&&members!=null)foreach(Dictionary<string,object> m in (object[])members)visit(m);};foreach(Dictionary<string,object> g in (object[])receipt["Groups"])visit(g);
  if(recovered.Values.Select(r=>r.Id).Distinct().Count()!=instances.Count)throw new Exception("Saved receipt does not cover every isolated native instance");record.Instances=recovered.Values.ToList();Write("copy.json",record);Console.WriteLine("Recovered "+record.Instances.Count+" copy bindings from exact saved receipt part paths and component references");
 }
 public static void VerifyHubReview(int pid,string output){
  app=(ISldWorks)typeof(CurrentAssignmentInspectionTest).GetMethod("Find",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{pid});code=Assembly.LoadFrom(Path.Combine(output,"beamng.cad.dll"));folder=Path.Combine(hubRoot,"assembly");app.CommandInProgress=true;
