   foreach(ModelDoc2 d in app.GetDocuments() as object[]??new object[0])if(d is PartDoc&&d.GetPathName().StartsWith(folder+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&d.GetSaveFlag())Save(d);
   Save(model);app.CloseDoc(model.GetTitle());Load();model.EditRebuild3();if(json.Serialize(MateHealth())!=health)throw new Exception("Mate state changed across reopening");
   var project=(Dictionary<string,object>)json.DeserializeObject(File.ReadAllText(record.Copy+".beamng-project.json"));var groups=((object[])project["Components"]).Cast<Dictionary<string,object>>().ToArray();var seen=new HashSet<string>();
   Action<object> walk=null;walk=v=>{var d=v as Dictionary<string,object>;if(d!=null){object k,r,c;if(d.TryGetValue("Kind",out k)&&object.Equals(k,"body")&&d.TryGetValue("Reference",out r)&&d.TryGetValue("ComponentReference",out c)&&seen.Add((string)c+"|"+(string)r)){if(!(Resolve(model,(string)c) is Component2)||!(Resolve(model,(string)r) is Body2))throw new Exception("Review assignment does not resolve");}foreach(var child in d.Values)walk(child);}else if(v is object[])foreach(var child in (object[])v)walk(child);};walk(project);
   foreach(var role in new[]{"rl_wheel","rr_wheel"}){var g=groups.Single(candidate=>object.Equals(candidate["MvpRole"],role));var selections=((object[])g["Selections"]).Cast<Dictionary<string,object>>().ToArray();if(selections.Length!=3)throw new Exception("Wheel assignment must include three bodies");var c=(Component2)Resolve(model,(string)selections[0]["ComponentReference"]);object info;var bodies=((object[])c.GetBodies3(-1,out info)).Cast<Body2>().ToArray();if(bodies.Length!=3)throw new Exception("Duplicate/missing native hub after rebuild");HubSeatCheck(bodies.Single(b=>b.Name.Contains("RestoredRearHub")));}
   if(seen.Count!=1000)throw new Exception("Expected 1000 unique body assignments after restoring two hubs; got "+seen.Count);var delta=instances.Max(p=>((double[])p.Value.Transform2.ArrayData).Zip(state[p.Key],(a,b)=>Math.Abs(a-b)).Max());if(delta>1e-6)throw new Exception("Saved pose changed");CheckOriginals();
   Write("hub-reopen-verification.json",new{status="passed",body_assignments=seen.Count,mates=Mates().Count(),mate_failures=MateFailures(),rest_transform_max_delta=delta,wheel_body_counts=new[]{3,3},working_files_unchanged=true,assembly=record.Copy});
   var first=groups.Single(g=>object.Equals(g["MvpRole"],"rl_wheel"));var instance=(Component2)Resolve(model,(string)((Dictionary<string,object>)((object[])first["Selections"])[0])["ComponentReference"]);model.ClearSelection2(true);instance.Select4(false,null,false);model.ViewZoomToSelection();model.ClearSelection2(true);model.GraphicsRedraw2();model.SaveBMP(Path.Combine(folder,"hub-closeup.bmp"),1200,900);Console.WriteLine("PASS reopen: 1000 body assignments, "+Mates().Count()+" mates; both hubs seated; original files unchanged");
  }finally{app.CommandInProgress=false;}
 }
 public static void RepairHubs(int pid,string output){
  app=(ISldWorks)typeof(CurrentAssignmentInspectionTest).GetMethod("Find",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{pid});code=Assembly.LoadFrom(Path.Combine(output,"beamng.cad.dll"));
  var path=@"H:\beamng project programs\BeamNG.cad\WorkingAsm\working-assembly-20261008-121423-3146e3\members-20261009-145459-2ddf1\Companion_e7c35c39.SLDASM";
  model=app.GetOpenDocumentByName(path) as ModelDoc2;if(model==null){int openError=0,openWarning=0;model=app.OpenDoc6(path,2,1,"",ref openError,ref openWarning) as ModelDoc2;if(model==null)throw new Exception("Cannot reopen saved working companion: "+openError);}Activate(model);folder=Path.Combine(hubRoot,"assembly");app.CommandInProgress=true;
