   var plans=((object[])json.DeserializeObject(File.ReadAllText(Path.Combine(hubRoot,"hub-plan.json")))).Cast<Dictionary<string,object>>().ToArray();
   var project=(Dictionary<string,object>)json.DeserializeObject(File.ReadAllText(record.Copy+".beamng-project.json"));var groups=((object[])project["Components"]).Cast<Dictionary<string,object>>().ToArray();
   if(!File.Exists(Path.Combine(folder,"working-assembly.json"))){oldInstances=record.Instances.ToDictionary(c=>c.Reference);CopyCompanionMetadata(project,record.Copy+".beamng-project.json");}
   var frames=groups.Where(g=>object.Equals(g["Template"],"calibrated_frame")).Select(g=>new{Id=g["Id"],Role="frame",Configuration=g["Configuration"],Selections=g["Selections"],Hull=g["Hull"]}).ToArray();File.WriteAllText(record.Copy+".truemesh-prep.json",json.Serialize(new{Format="beamng-cad-preparation",Version=1,SourceDocument=record.Copy,Assignments=frames}));
   var baseline=MateHealth();var healthBefore=json.Serialize(baseline);var transforms=instances.ToDictionary(p=>p.Key,p=>(double[])p.Value.Transform2.ArrayData);var report=new List<object>();
   var faceKey=code.GetType("BeamNG.Cad.Preparation.AssociationAssembly").GetMethod("FaceKey",BindingFlags.Static|BindingFlags.NonPublic);
   foreach(var plan in plans){
    var role=(string)plan["role"];var target=instances.Values.Single(c=>string.Equals(c.GetPathName(),record.Files[(string)plan["target_part"]],StringComparison.OrdinalIgnoreCase));var part=(ModelDoc2)target.GetModelDoc2();
    part.EditRebuild3();var before=((object[])((PartDoc)part).GetBodies2(-1,false)).Cast<Body2>().ToArray();var names=before.Select(b=>b.Name).ToArray();var references=before.ToDictionary(b=>b.Name,b=>Ref(part,b));
    if(role=="rr_wheel"&&before.Length==3&&before.Count(b=>b.Name.Contains("RestoredRearHub"))==1){var propagated=before.Single(b=>b.Name.Contains("RestoredRearHub"));HubSeatCheck(propagated);Save(part);Activate(model);HubBind(groups.Single(g=>object.Equals(g["MvpRole"],role)),target);report.Add(new{role=role,part=part.GetPathName(),bodies=3,mirrored_hub_propagated=true,existing_body_references_preserved=true});Console.WriteLine("PASS right hub propagated through native mirror; mounting pattern and seat verified");continue;}
    if(before.Length!=2)throw new Exception(role+": expected untouched rim and tire; found "+before.Length+" bodies. Inspect propagated mirror state before adding another hub.");
    var original=app.GetOpenDocumentByName((string)plan["original_part"]) as ModelDoc2;var own=original==null;int e=0,w=0;
    if(own){var visible=app.GetDocumentVisible(1);try{app.DocumentVisible(false,1);original=app.OpenDoc6((string)plan["original_part"],1,3,"",ref e,ref w) as ModelDoc2;}finally{app.DocumentVisible(visible,1);}}
    if(original==null)throw new Exception("Cannot read retained hub source: "+e);
    try{
     var sourceHub=((object[])((PartDoc)original).GetBodies2(-1,false)).Cast<Body2>().Single(b=>b.Name==(string)plan["body"]);var body=(Body2)sourceHub.Copy2(false);var sourceFaces=((object[])sourceHub.GetFaces()).Cast<Face2>().ToArray();var copiedFaces=((object[])body.GetFaces()).Cast<Face2>().ToArray();
     var sourcePaint=sourceFaces.GroupBy(f=>(string)faceKey.Invoke(null,new object[]{f})).ToDictionary(g=>g.Key,g=>{var f=g.First();return f.HasMaterialPropertyValues()?(double[])f.GetMaterialPropertyValues2(1,null):sourceHub.HasMaterialPropertyValues()?(double[])sourceHub.MaterialPropertyValues2:(double[])original.MaterialPropertyValues;});
