     var transformed=copiedFaces.Select((f,i)=>new{Key=(string)faceKey.Invoke(null,new object[]{f}),Color=paints[i]}).GroupBy(p=>p.Key).ToDictionary(g=>g.Key,g=>g.First().Color);
     Activate(part);var feature=((PartDoc)part).CreateFeatureFromBody3(body,false,(int)swCreateFeatureBodyOpts_e.swCreateFeatureBodyCheck) as Feature;if(feature==null)throw new Exception("Hub import failed");feature.Name="Recovered original rear hub";
