     foreach(Face2 f in (object[])hub.GetFaces()){double[] color;if(!transformed.TryGetValue((string)faceKey.Invoke(null,new object[]{f}),out color))throw new Exception("Hub face correspondence changed on import");if(color!=null)f.MaterialPropertyValues=color;}
     part.EditRebuild3();Save(part);var after=((object[])((PartDoc)part).GetBodies2(-1,false)).Cast<Body2>().ToArray();if(after.Length!=3||references.Any(p=>!(Resolve(part,p.Value) is Body2)))throw new Exception("Existing rim/tire identities changed");hub=after.Single(b=>b.Name=="RestoredRearHub");var actual=(double[])hub.GetMassProperties(1);if(Math.Abs(actual[3]-volume)>1e-11||actual.Take(3).Zip(expected.Take(3),(a,b)=>Math.Abs(a-b)).Max()>1e-8)throw new Exception("Hub placement/volume check failed");
